const ImageIcon: Icon = /* @__PURE__ */ createIcon("image", iconNode27)

/* -------------------------------------------------------------------------------------------------
 * Shared pieces for renderers
 * -----------------------------------------------------------------------------------------------*/

/** Header detail with a trailing fact that never truncates: `query` + `8 results`. */
function ToolDetail({ children, meta }: { children?: React.ReactNode; meta?: React.ReactNode }) {
  return (
    <span data-slot="tool-detail" className="inline-flex max-w-full min-w-0 items-baseline gap-2">
      {children ? <span className="min-w-0 truncate">{children}</span> : null}
      {meta !== undefined && meta !== null && meta !== false ? (
        <span className="shrink-0 font-sans tabular-nums">{meta}</span>
      ) : null}
    </span>
  )
}

/**
 * An image generation tool call: the prompt in the header, the frames with the progressive reveal
 * while it runs, then the images with their actions. Open by default, since the image is the
 * point of the call.
 */
export function ToolImageGen({
  name = "generate_image",
  prompt,
  revisedPrompt,
  images = [],
  count,
  aspectRatio = "1:1",
  progress,
  blocked,
  onUpscale,
  onVary,
  onUseAsReference,
  defaultOpen = true,
  ...props
}: ToolImageGenProps) {
  const state = props.state
  const running = isToolRunning(state, props.decision)
  const done = state === "output-available"
  const policy = blocked ?? (state === "output-error" && POLICY.test(String(props.errorText ?? "")))
  const total = Math.min(4, Math.max(1, count ?? (images.length || 1)))
  const plural = total > 1

  const status: GenerationStatus | null = running
    ? "generating"
    : done
      ? "done"
      : state === "output-error"
        ? policy
          ? "blocked"
          : "failed"
        : null

  // Failures use the call's own error section with Retry. A refusal gets calm copy in a row
  // instead of empty frames: inside a tool call there is no layout to hold.
  const body =
    status === "blocked" ? (
      <div data-slot="tool-image-gen-blocked" className="flex items-start gap-2.5">
        <ShieldIcon aria-hidden="true" className="text-(color:--chatcn-fg-muted) mt-0.5 size-4 shrink-0" />
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-medium">This image wasn’t created</p>
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">
            The prompt may go against the content policy. Try describing the scene and mood instead
            of a specific person or brand.
          </p>
        </div>
      </div>
    ) : status && status !== "failed" && prompt !== undefined ? (
      <>
        <ImageGeneration
          prompt={prompt}
          status={status}
          images={images}
          count={total}
          aspectRatio={aspectRatio}
          progress={progress}
          showPrompt={false}
          onUpscale={onUpscale}
          onVary={onVary}
          onUseAsReference={onUseAsReference}
        />
        {done && revisedPrompt && revisedPrompt !== prompt ? (
          <ToolCallSection label="Revised prompt">
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{revisedPrompt}</p>
          </ToolCallSection>
        ) : null}
      </>
    ) : undefined

  return (
    <ToolCall
      name={name}
      icon={<ImageIcon />}
      statusLabel={status === "blocked" ? "Blocked" : undefined}
      title={
        running
          ? plural
            ? "Generating images"
            : "Generating image"
          : done
            ? plural
              ? `Generated ${total} images`
              : "Generated image"
            : plural
              ? "Generate images"
              : "Generate image"
      }
      detail={<ToolDetail>{prompt}</ToolDetail>}
      defaultOpen={defaultOpen}
      {...props}
    >
      {body}
    </ToolCall>
  )
}

/** True once a tool call will not change again. */
function isTerminalToolState(state: ToolDisplayState): boolean {
  return (
    state === "output-available" ||
    state === "output-error" ||
    state === "output-denied" ||
    state === "cancelled"
  )
}

/** Display state for a tool part; unfinished calls in a stopped response become `cancelled`. */
function getToolDisplayState(
  part: Pick<ChatcnToolPart, "state">,
  options?: { stopped?: boolean },
): ToolDisplayState {
  return options?.stopped && !isTerminalToolState(part.state) ? "cancelled" : part.state
}

/** Tool name for `tool-${name}` and `dynamic-tool` parts. */
function getToolName(part: Pick<ChatcnToolPart, "type" | "toolName">): string {
  if (part.type === "dynamic-tool") return part.toolName ?? ""
  return part.type.slice("tool-".length)
}

/* -------------------------------------------------------------------------------------------------
 * From a message part
 * -----------------------------------------------------------------------------------------------*/

/**
 * Maps a tool part (chatcn contract or AI SDK `UIMessage` part) to `ToolCall` props.
 * `<ToolCall {...toolCallPropsFromPart(part)} onApprove={...} />`
 */
function toolCallPropsFromPart(
  part: ChatcnToolPart,
  options?: { stopped?: boolean },
): Pick<
  ToolCallProps,
  "name" | "state" | "input" | "inputText" | "output" | "errorText" | "approval" | "decision"
> &
  Partial<Pick<ToolCallProps, "title">> {
  const state = getToolDisplayState(part, options)
  const approval = part.approval
  return {
    name: getToolName(part),
    ...(part.title ? { title: part.title } : {}),
    state,
    input: part.input,
    inputText: typeof part.rawInput === "string" ? part.rawInput : undefined,
    output: part.output,
    errorText: part.errorText,
    approval:
      approval && state === "approval-requested"
        ? { id: approval.id, reason: approval.requestReason }
        : undefined,
    decision:
      approval && approval.approved !== undefined
        ? { approved: approval.approved, reason: approval.reason }
        : undefined,
  }
}

/**
 * Lifecycle props from a tool part. A `preliminary` output (a tool still streaming its result)
 * keeps the call in its running state, so timers keep ticking and output keeps streaming.
 */
function toolBasePropsFromPart({
  part,
  stopped,
  variant,
  onApprove,
  onDeny,
  onRetry,
  durationMs,
  startedAt,
  open,
  defaultOpen,
  onOpenChange,
  className,
}: ToolRendererProps): ToolBaseProps {
  const { name, state, errorText, approval, decision } = toolCallPropsFromPart(part, { stopped })
  const preliminary = part.preliminary === true && state === "output-available"
  return {
    name,
    state: preliminary ? (stopped ? "cancelled" : "input-available") : state,
    errorText,
    approval,
    decision,
    variant,
    onApprove,
    onDeny,
    onRetry,
    durationMs,
    startedAt,
    open,
    defaultOpen,
    onOpenChange,
    className,
  }
}

/** `"1024x1536"` to `"2:3"`, `"16:9"` stays. Unknown sizes fall back to square. */
export function aspectFromInput(input: unknown): AspectRatio {
  const ratio = pickString(input, "aspect_ratio", "aspectRatio", "ratio")
  if (ratio && /^\d+(\.\d+)?:\d+(\.\d+)?$/.test(ratio)) return ratio as AspectRatio
  const size = pickString(input, "size", "resolution")
  const match = size ? /^(\d+)\s*[x×]\s*(\d+)$/.exec(size) : null
  if (match) {
    const w = Number(match[1])
    const h = Number(match[2])
    const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b))
    const d = gcd(w, h) || 1
    return `${w / d}:${h / d}` as AspectRatio
  }
  return "1:1"
}

export function ToolImageGenPart(props: ToolRendererProps) {
  const { part } = props
  const { images, revisedPrompt } = generatedImagesFrom(part.output)
  return (
    <ToolImageGen
      {...toolBasePropsFromPart(props)}
      prompt={pickString(part.input, "prompt", "description", "query")}
      revisedPrompt={revisedPrompt}
      images={images}
      count={pickNumber(part.input, "n", "count", "num_images", "numberOfImages")}
      aspectRatio={aspectFromInput(part.input)}
      progress={pickNumber(part.output, "progress", "percent")}
    />
  )
}

/** Tool names this renderer handles. Spread into your renderer map. */
export const toolImageGenRenderers: ToolRendererMap = {
  generate_image: ToolImageGenPart,
  image_generation: ToolImageGenPart,
  create_image: ToolImageGenPart,
  text_to_image: ToolImageGenPart,
  dall_e: ToolImageGenPart,
}

export default ToolImageGen

